head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > E > ondateselect]<br/>Calendar 컴포넌트에서 날짜를 선택할 때 발생합니다.",
    "validation" : [
        "Today 버튼을 클릭하면 ondateselect 이벤트가 발생합니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 라벨: 수동 테스트 안내
    $c.gcm.createLabel('label="[수동 테스트 안내] Today 버튼을 클릭하면 ondateselect 이벤트가 발생합니다."', '', 'label1');

    // todaySelect=true: Today 버튼 클릭 시에도 ondateselect 이벤트가 발생하도록 활성화
    // 엔진 calendar.js:5143 - this.options.renderType=="native" 또는 this.options.todaySelect 일 때 fireEvent
    let properties = {
        todaySelect : "true"
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["ondateselect"]);

    await $c.gcm.createBasicCalendar(cList, eList);
}



// Today 버튼 클릭 시 ondateselect 이벤트 발생 (validation 1)
scwin.target1_ondateselect = function (date, dateObject) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_ondateselect=====");
};
